30: class SignalLoginPaymentViewModel(
31:   private val repository: RegistrationRepository,
32:   private val parentEventEmitter: (RegistrationFlowEvent) -> Unit
33: ) : EventDrivenViewModel<SignalLoginPaymentScreenEvents>(TAG) {
34: 
35:   companion object {
36:     private val TAG = Log.tag(SignalLoginPaymentViewModel::class)
37:   }
38: 
39:   private val _state = MutableStateFlow(SignalLoginPaymentState(showManualReceiptCredentialEntry = repository.isDebugBuild))
40:   val state: StateFlow<SignalLoginPaymentState> = _state.asStateFlow()
41: 
42:   private val _actions = Channel<SignalLoginPaymentScreenActions>(Channel.BUFFERED)
43:   val actions: Flow<SignalLoginPaymentScreenActions> = _actions.receiveAsFlow()
44: 
45:   init {
46:     _state
47:       .onEach { Log.d(TAG, "[State] $it") }
48:       .launchIn(viewModelScope)
49: 
50:     onEvent(SignalLoginPaymentScreenEvents.Initialize)
51:   }
52: 
53:   override suspend fun processEvent(event: SignalLoginPaymentScreenEvents) {
54:     applyEvent(_state.value, event, parentEventEmitter) { _state.value = it }
55:   }
56: 
57:   @VisibleForTesting
58:   suspend fun applyEvent(
59:     state: SignalLoginPaymentState,
60:     event: SignalLoginPaymentScreenEvents,
61:     parentEventEmitter: (RegistrationFlowEvent) -> Unit,
62:     stateEmitter: (SignalLoginPaymentState) -> Unit
63:   ) {
64:     when (event) {
65:       is SignalLoginPaymentScreenEvents.Initialize -> {
66:         // TODO [phonenumberless] Load the price from the billing library and populate SignalLoginPaymentState.formattedPrice.
67:       }
68: 
69:       is SignalLoginPaymentScreenEvents.BackClicked -> {
70:         parentEventEmitter.navigateBack()
71:       }
72: 
73:       is SignalLoginPaymentScreenEvents.LearnMoreClicked -> {
74:         _actions.trySend(SignalLoginPaymentScreenActions.OpenLearnMoreArticle)
75:       }
76: 
77:       is SignalLoginPaymentScreenEvents.OptionSelected -> {
78:         stateEmitter(state.copy(selectedOption = event.option))
79:       }
80: 
81:       is SignalLoginPaymentScreenEvents.ManualReceiptCredentialChanged -> {
82:         stateEmitter(state.copy(manualReceiptCredential = event.value))
83:       }
84: 
85:       is SignalLoginPaymentScreenEvents.ContinueClicked -> {
86:         if (state.manualReceiptCredential.isNotBlank) {
87:           var localState = state.copy(showSpinner = true)
88:           stateEmitter(localState)
89:           localState = applyManualReceiptCredentialSubmitted(localState, parentEventEmitter)
90:           stateEmitter(localState.copy(showSpinner = false))
91:         } else if (state.selectedOption == SignalLoginPaymentState.Option.ExistingLogin) {
92:           parentEventEmitter.navigateTo(RegistrationRoute.SignalLoginCredentialEntry())
93:         } else {
94:           // TODO [phonenumberless] Launch the purchase flow.
95:           Log.i(TAG, "Continue clicked for ${state.selectedOption}, but the purchase flow isn't implemented yet.")
96:         }
97:       }
98: 
99:       is SignalLoginPaymentScreenEvents.NetworkErrorDialogDismissed -> {
100:         stateEmitter(state.copy(dialogs = state.dialogs.copy(networkError = false)))
101:       }
102: 
103:       is SignalLoginPaymentScreenEvents.UnknownErrorDialogDismissed -> {
104:         stateEmitter(state.copy(dialogs = state.dialogs.copy(unknownError = false)))
105:       }
106: 
107:       is SignalLoginPaymentScreenEvents.PurchaseFailedDialogDismissed -> {
108:         stateEmitter(state.copy(dialogs = state.dialogs.copy(purchaseFailed = false)))
109:       }
110: 
111:       is SignalLoginPaymentScreenEvents.InvalidReceiptCredentialDialogDismissed -> {
112:         stateEmitter(state.copy(dialogs = state.dialogs.copy(invalidReceiptCredential = false)))
113:       }
114:     }
115:   }
116: 
117:   /**
118:    * Redeems the manually-pasted receipt credential by building its presentation and registering a numberless account
119:    * with it, bypassing the (unfinished) purchase flow entirely.
120:    */
121:   private suspend fun applyManualReceiptCredentialSubmitted(
122:     state: SignalLoginPaymentState,
123:     parentEventEmitter: (RegistrationFlowEvent) -> Unit
124:   ): SignalLoginPaymentState {
125:     val presentation = try {
126:       repository.createReceiptCredentialPresentation(state.manualReceiptCredential.decode())
127:     } catch (e: Exception) {
128:       Log.w(TAG, "[ManualReceipt] The pasted value could not be parsed as a receipt credential.", e)
129:       return state.copy(dialogs = state.dialogs.copy(invalidReceiptCredential = true))
130:     }
131: 
132:     return when (val result = repository.registerAccountWithoutPhoneNumber(presentation)) {
133:       is RequestResult.Success -> {
134:         Log.i(TAG, "[ManualReceipt] Successfully registered without a phone number.")
135:         val (response, keyMaterial, aci) = result.result
136: 
137:         parentEventEmitter(RegistrationFlowEvent.Registered(aci, keyMaterial.accountEntropyPool, response.storageCapable, phoneNumberless = response.e164 == null))
138:         parentEventEmitter.navigateTo(RegistrationRoute.SignalLoginInfo)
139:         state
140:       }
141:       is RequestResult.NonSuccess -> {
142:         when (val error = result.error) {
143:           is RegisterAccountError.InvalidReceiptCredentialPresentation -> {
144:             Log.w(TAG, "[ManualReceipt] The service rejected the receipt credential presentation. Message: ${error.message}")
145:             state.copy(dialogs = state.dialogs.copy(invalidReceiptCredential = true))
146:           }
147:           is RegisterAccountError.DeviceTransferPossible -> {
148:             Log.w(TAG, "[ManualReceipt] Got told a device transfer is possible despite asking to skip it.")
149:             state.copy(dialogs = state.dialogs.copy(unknownError = true))
150:           }
151:           is RegisterAccountError.InvalidRequest -> {
152:             Log.w(TAG, "[ManualReceipt] Invalid request. Message: ${error.message}")
153:             state.copy(dialogs = state.dialogs.copy(unknownError = true))
154:           }
155:           is RegisterAccountError.RateLimited -> {
156:             Log.w(TAG, "[ManualReceipt] Rate limited (retryAfter: ${error.retryAfter}).")
157:             state.copy(dialogs = state.dialogs.copy(unknownError = true))
158:           }
159:           else -> {
160:             Log.w(TAG, "[ManualReceipt] Unexpected registration error for a numberless registration: $error")
161:             state.copy(dialogs = state.dialogs.copy(unknownError = true))
162:           }
163:         }
164:       }
165:       is RequestResult.RetryableNetworkError -> {
166:         Log.w(TAG, "[ManualReceipt] Network error.", result.networkError)
167:         state.copy(dialogs = state.dialogs.copy(networkError = true))
168:       }
169:       is RequestResult.ApplicationError -> {
170:         Log.w(TAG, "[ManualReceipt] Application error.", result.cause)
171:         state.copy(dialogs = state.dialogs.copy(unknownError = true))
172:       }
173:     }
174:   }
175: 
176:   class Factory(
177:     private val repository: RegistrationRepository,
178:     private val parentEventEmitter: (RegistrationFlowEvent) -> Unit
179:   ) : ViewModelProvider.Factory {
180:     @Suppress("UNCHECKED_CAST")
181:     override fun <T : ViewModel> create(modelClass: Class<T>): T {
182:       return SignalLoginPaymentViewModel(repository, parentEventEmitter) as T
183:     }
184:   }
185: }

