  open suspend fun getLoginConfiguration(): LoginConfiguration = LoginConfiguration()

  /** Trade a paid purchase identifier for a receipt credential that can be presented to register. */
  open suspend fun createLoginReceiptCredential(purchaseToken: String, receiptCredentialRequestContext: ByteArray): CreateLoginReceiptCredentialResult = CreateLoginReceiptCredentialResult.Pending

  /** Verify an issued receipt credential, producing a presentation the service will accept. */
  open fun verifyReceiptCredential(credential: ReceiptCredential): ReceiptCredentialResult = ReceiptCredentialResult.Failure()

  open fun createReceiptCredentialPresentation(credential: ReceiptCredential): ReceiptCredentialPresentation = ReceiptCredentialPresentation()
