package org.signal.registration.screens.signalloginpayment

import org.signal.core.util.billing.OneTimePurchasePreparation

/**
 * State for the Signal Login purchase screen, where the user either buys a Signal Login or indicates they already have
 * one.
 */
data class SignalLoginPaymentState(
  val selectedOption: Option = Option.Purchase,
  /** Whether Play Billing can be used right now. Checked again every time the screen comes to the foreground. */
  val paymentAvailability: PaymentAvailability = PaymentAvailability.Available,
  /** The purchase price, or why there isn't one yet. */
  val price: Price = Price.Loading,
  /** Set while a purchase is being prepared, so the UI knows whether "continue" can launch a sheet. */
  val purchasePreparation: OneTimePurchasePreparation? = null,
  /**
   * True when the account already owns a paid purchase that hasn't been redeemed. Registration can proceed without
   * paying again, so this stands in for a price as a reason to let the user continue.
   */
  val hasUnredeemedPurchase: Boolean = false,
  /**
   * A manually-pasted, base64-encoded receipt credential. A debug affordance that lets us skip payment entirely and
   * register with a credential issued out-of-band. When non-blank, the continue button redeems it directly.
   */
  val manualReceiptCredential: ManualReceiptCredential = ManualReceiptCredential.EMPTY,
  val showManualReceiptCredentialEntry: Boolean = false,
  val showSpinner: Boolean = false,
  val dialogs: Dialogs = Dialogs()
) {
  /**
   * Localized, currency-formatted price of the one-time purchase, exactly as the billing library reported it. Null
   * until the price has been loaded, or if it can't be loaded at all.
   */
  val formattedPrice: String?
    get() = (price as? Price.Available)?.formattedPrice

  /** Whether we know enough to let the user act on the selected option. */
  val isActionEnabled: Boolean
    get() = !showSpinner && (
      manualReceiptCredential.isNotBlank ||
        selectedOption == Option.ExistingLogin ||
        price is Price.Available ||
        hasUnredeemedPurchase
      )

  /** The purchase can be offered when we know a price, or when there's already something paid to redeem. */
  val isPurchaseAvailable: Boolean
    get() = price is Price.Available || hasUnredeemedPurchase

  /**
   * What we know about the one-time purchase price. Only [Available] and an already-owned purchase may lead to a
   * charge; everything else blocks submission.
   */
  sealed interface Price {
    /** We haven't asked yet, or we asked and the answer is in flight. */
    data object Loading : Price

    /** The purchase is possible, at this localized, currency-formatted price. */
    data class Available(val formattedPrice: String) : Price

    /** The lookup failed in a way that may succeed next time; the user is offered a retry. */
    data object TransientError : Price

    /** Payment cannot proceed, and retrying on this device won't change that. */
    data object Unavailable : Price
  }

  enum class Option {
    /** Buy a new Signal Login. */
    Purchase,

    /** Register with an account key the user already owns. */
    ExistingLogin
  }

  data class Dialogs(
    val networkError: Boolean = false,
    val unknownError: Boolean = false,
    val purchaseFailed: Boolean = false,
    val invalidReceiptCredential: Boolean = false,
    /**
     * Payment can't be used right now. Shown for both the recoverable (Play services updating) and terminal cases; the
     * copy differs, and only the terminal case takes the purchase option away.
     */
    val paymentUnavailable: Boolean = false
  )
}

