package org.signal.registration.screens.signalloginpayment

import androidx.annotation.VisibleForTesting
import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.channels.Channel
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.launchIn
import kotlinx.coroutines.flow.onEach
import kotlinx.coroutines.flow.receiveAsFlow
import org.signal.core.ui.compose.EventDrivenViewModel
import org.signal.core.util.billing.OneTimePurchaseApi
import org.signal.core.util.billing.OneTimePurchasePreparation
import org.signal.core.util.billing.OneTimePurchaseResult
import org.signal.core.util.billing.PurchaseLauncher
import org.signal.core.util.logging.Log
import org.signal.libsignal.net.RequestResult
import org.signal.network.api.RegistrationApiV2.RegisterAccountError
import org.signal.registration.RegistrationFlowEvent
import org.signal.registration.RegistrationRepository
import org.signal.registration.RegistrationRoute
import org.signal.registration.SignalLoginPurchaseStep
import org.signal.registration.screens.util.navigateBack
import org.signal.registration.screens.util.navigateTo
import org.signal.registration.util.SignalLoginPurchaseStore

class SignalLoginPaymentViewModel(
  private val repository: RegistrationRepository,
  private val purchaseStep: SignalLoginPurchaseStep,
  private val parentEventEmitter: (RegistrationFlowEvent) -> Unit
) : EventDrivenViewModel<SignalLoginPaymentScreenEvents>(TAG) {

  companion object {
    private val TAG = Log.tag(SignalLoginPaymentViewModel::class)
  }

  private val _state = MutableStateFlow(SignalLoginPaymentState(showManualReceiptCredentialEntry = repository.isDebugBuild))
  val state: StateFlow<SignalLoginPaymentState> = _state.asStateFlow()

  private val _actions = Channel<SignalLoginPaymentScreenActions>(Channel.BUFFERED)
  val actions: Flow<SignalLoginPaymentScreenActions> = _actions.receiveAsFlow()

  init {
    _state
      .onEach { Log.d(TAG, "[State] $it") }
      .launchIn(viewModelScope)

    onEvent(SignalLoginPaymentScreenEvents.Initialize)
  }

  override suspend fun processEvent(event: SignalLoginPaymentScreenEvents) {
    applyEvent(_state.value, event, parentEventEmitter) { _state.value = it }
  }

  @VisibleForTesting
  suspend fun applyEvent(
    state: SignalLoginPaymentState,
    event: SignalLoginPaymentScreenEvents,
    parentEventEmitter: (RegistrationFlowEvent) -> Unit,
    stateEmitter: (SignalLoginPaymentState) -> Unit
  ) {
    when (event) {
      is SignalLoginPaymentScreenEvents.Initialize,
      is SignalLoginPaymentScreenEvents.Foreground,
      is SignalLoginPaymentScreenEvents.RetryPriceClicked -> {
        refreshPaymentAvailability(state, stateEmitter)
      }

      is SignalLoginPaymentScreenEvents.BackClicked -> {
        parentEventEmitter.navigateBack()
      }

      is SignalLoginPaymentScreenEvents.LearnMoreClicked -> {
        _actions.trySend(SignalLoginPaymentScreenActions.OpenLearnMoreArticle)
      }

      is SignalLoginPaymentScreenEvents.OptionSelected -> {
        stateEmitter(state.copy(selectedOption = event.option))
      }

      is SignalLoginPaymentScreenEvents.ManualReceiptCredentialChanged -> {
        stateEmitter(state.copy(manualReceiptCredential = event.value))
      }

      is SignalLoginPaymentScreenEvents.ContinueClicked -> {
        if (state.manualReceiptCredential.isNotBlank) {
          var localState = state.copy(showSpinner = true)
          stateEmitter(localState)
          localState = applyManualReceiptCredentialSubmitted(localState, parentEventEmitter)
          stateEmitter(localState.copy(showSpinner = false))
        } else if (state.selectedOption == SignalLoginPaymentState.Option.ExistingLogin) {
          parentEventEmitter.navigateTo(RegistrationRoute.SignalLoginCredentialEntry())
        } else {
          continuePurchase(state, parentEventEmitter, stateEmitter)
        }
      }

      is SignalLoginPaymentScreenEvents.PurchaseFlowCompleted -> {
        // The only thing that can complete a purchase. The held spinner is cleared here, and no earlier than here.
        applyPurchaseFlowCompleted(state, event.result, parentEventEmitter, stateEmitter)
      }

      is SignalLoginPaymentScreenEvents.ResolvePaymentServicesClicked -> {
        _actions.trySend(SignalLoginPaymentScreenActions.ResolvePaymentServices)
      }

      is SignalLoginPaymentScreenEvents.NetworkErrorDialogDismissed -> {
        stateEmitter(state.copy(dialogs = state.dialogs.copy(networkError = false)))
      }

      is SignalLoginPaymentScreenEvents.UnknownErrorDialogDismissed -> {
        stateEmitter(state.copy(dialogs = state.dialogs.copy(unknownError = false)))
      }

      is SignalLoginPaymentScreenEvents.PurchaseFailedDialogDismissed -> {
        stateEmitter(state.copy(dialogs = state.dialogs.copy(purchaseFailed = false)))
      }

      is SignalLoginPaymentScreenEvents.InvalidReceiptCredentialDialogDismissed -> {
        stateEmitter(state.copy(dialogs = state.dialogs.copy(invalidReceiptCredential = false)))
      }

      is SignalLoginPaymentScreenEvents.PaymentUnavailableDialogDismissed -> {
        stateEmitter(state.copy(dialogs = state.dialogs.copy(paymentUnavailable = false)))
      }
    }
  }

  /**
   * Re-derive whether payment is possible and how much it costs.
   *
   * Availability is asked for fresh every time rather than remembered, because the user may have just gone off to fix
   * Play services. The restore step also runs here, which is what lets a purchase paid for in a previous process show
   * up as "continue" instead of "buy again".
   */
  private suspend fun refreshPaymentAvailability(
    state: SignalLoginPaymentState,
    stateEmitter: (SignalLoginPaymentState) -> Unit
  ) {
    val restored = purchaseStep.restoreUnredeemedPurchase()
    val availability = repository.getPaymentAvailability()

    stateEmitter(
      state.copy(
        paymentAvailability = availability,
        hasUnredeemedPurchase = restored != null,
        price = SignalLoginPaymentState.Price.Loading,
        purchasePreparation = null
      )
    )

    stateEmitter(applyPrice(state.copy(paymentAvailability = availability, hasUnredeemedPurchase = restored != null), purchaseStep.loadPrice()))
  }

  private fun applyPrice(state: SignalLoginPaymentState, price: SignalLoginPurchaseStep.Price): SignalLoginPaymentState =
    when (price) {
      is SignalLoginPurchaseStep.Price.Available ->
        state.copy(price = SignalLoginPaymentState.Price.Available(price.formattedPrice), dialogs = state.dialogs.copy(paymentUnavailable = false))
      // Recoverable: Play services needs attention, so the purchase option stays enabled and the user can come back.
      SignalLoginPurchaseStep.Price.NeedsServiceUpdate ->
        state.copy(price = SignalLoginPaymentState.Price.TransientError, dialogs = state.dialogs.copy(paymentUnavailable = true))
      SignalLoginPurchaseStep.Price.TransientError ->
        state.copy(price = SignalLoginPaymentState.Price.TransientError, dialogs = state.dialogs.copy(paymentUnavailable = false))
      // Terminal: payment can't proceed here, so we say so and leave the other registration choices alone.
      SignalLoginPurchaseStep.Price.Unavailable ->
        state.copy(price = SignalLoginPaymentState.Price.Unavailable, dialogs = state.dialogs.copy(paymentUnavailable = true))
      SignalLoginPurchaseStep.Price.NoProductConfigured ->
        state.copy(price = SignalLoginPaymentState.Price.Unavailable, dialogs = state.dialogs.copy(paymentUnavailable = true))
    }

  /**
   * The user committed to buying a Signal Login.
   *
   * If billing already owns an unconsumed purchase we go straight to redeeming it — no sheet, no second charge.
   * Otherwise we prepare the purchase and, if it comes back ready, hand a launcher to the UI layer and *hold* the
   * spinner until that sheet tells us how it settled.
   */
  private suspend fun continuePurchase(
    state: SignalLoginPaymentState,
    parentEventEmitter: (RegistrationFlowEvent) -> Unit,
    stateEmitter: (SignalLoginPaymentState) -> Unit
  ) {
    if (state.hasUnredeemedPurchase) {
      Log.i(TAG, "Redeeming a purchase that was already paid for.")
      stateEmitter(state.copy(showSpinner = true))
      stateEmitter(redeem(state.copy(showSpinner = true), purchase = null, parentEventEmitter, stateEmitter).copy(showSpinner = false))
      return
    }

    if (state.price !is SignalLoginPaymentState.Price.Available) {
      Log.i(TAG, "Refusing to start a purchase without a usable price.")
      return
    }

    when (val preparation = purchaseStep.preparePurchase()) {
      is OneTimePurchasePreparation.Ready -> {
        stateEmitter(state.copy(purchasePreparation = preparation, showSpinner = true))
        _actions.trySend(SignalLoginPaymentScreenActions.LaunchPurchaseSheet(preparation.launcher))
      }
      is OneTimePurchasePreparation.AlreadyPurchased -> {
        Log.i(TAG, "Billing reports this account already owns the purchase; redeeming instead of charging.")
        stateEmitter(state.copy(purchasePreparation = preparation, showSpinner = true))
        stateEmitter(redeem(state.copy(purchasePreparation = preparation, showSpinner = true), preparation.purchase, parentEventEmitter, stateEmitter).copy(showSpinner = false))
      }
      OneTimePurchasePreparation.Unavailable -> {
        stateEmitter(state.copy(dialogs = state.dialogs.copy(paymentUnavailable = true)))
      }
      OneTimePurchasePreparation.NetworkError -> {
        stateEmitter(state.copy(dialogs = state.dialogs.copy(networkError = true)))
      }
      OneTimePurchasePreparation.Failed -> {
        stateEmitter(state.copy(dialogs = state.dialogs.copy(purchaseFailed = true)))
      }
    }
  }

  /**
   * Settle the external purchase sheet.
   *
   * A cancellation is a settled outcome, not an error: the held spinner comes down, no dialog appears, and nothing asks
   * the service for a receipt. The screen is simply usable again.
   */
  private suspend fun applyPurchaseFlowCompleted(
    state: SignalLoginPaymentState,
    result: OneTimePurchaseResult,
    parentEventEmitter: (RegistrationFlowEvent) -> Unit,
    stateEmitter: (SignalLoginPaymentState) -> Unit
  ) {
    when (result) {
      is OneTimePurchaseResult.Success -> {
        stateEmitter(state.copy(purchasePreparation = null, showSpinner = true))
        stateEmitter(redeem(state.copy(purchasePreparation = null, showSpinner = true), result.purchase, parentEventEmitter, stateEmitter).copy(showSpinner = false))
      }
      OneTimePurchaseResult.UserCancelled -> {
        Log.i(TAG, "The purchase sheet was cancelled; nothing was charged and nothing was registered.")
        stateEmitter(state.copy(purchasePreparation = null, showSpinner = false))
      }
      OneTimePurchaseResult.Unavailable -> {
        stateEmitter(state.copy(purchasePreparation = null, showSpinner = false, dialogs = state.dialogs.copy(paymentUnavailable = true)))
      }
      OneTimePurchaseResult.NetworkError -> {
        stateEmitter(state.copy(purchasePreparation = null, showSpinner = false, dialogs = state.dialogs.copy(networkError = true)))
      }
      OneTimePurchaseResult.Failed -> {
        stateEmitter(state.copy(purchasePreparation = null, showSpinner = false, dialogs = state.dialogs.copy(purchaseFailed = true)))
      }
    }
  }

  /**
   * Turn a paid purchase into a registered account.
   *
   * Every outcome other than [SignalLoginPurchaseStep.Redemption.Registered] leaves the purchase on disk, so the next
   * attempt redeems rather than charges. Registration that did happen is announced to the parent *before* navigating,
   * so the next screen sees the issued account ID and recovery key.
   */
  private suspend fun redeem(
    state: SignalLoginPaymentState,
    purchase: org.signal.core.util.billing.OneTimePurchase?,
    parentEventEmitter: (RegistrationFlowEvent) -> Unit,
    stateEmitter: (SignalLoginPaymentState) -> Unit
  ): SignalLoginPaymentState = when (val redemption = purchaseStep.redeem(purchase)) {
    is SignalLoginPurchaseStep.Redemption.Registered -> {
      val data = redemption.data
      parentEventEmitter(
        RegistrationFlowEvent.Registered(
          aci = data.aci,
          accountEntropyPool = data.keyMaterial.accountEntropyPool,
          storageCapable = data.response.storageCapable,
          phoneNumberless = redemption.phoneNumberless
        )
      )
      parentEventEmitter.navigateTo(RegistrationRoute.SignalLoginInfo, popCurrent = true)
      state.copy(price = SignalLoginPaymentState.Price.Available(state.formattedPrice ?: ""), hasUnredeemedPurchase = false)
    }
    SignalLoginPurchaseStep.Redemption.ReceiptPending -> {
      Log.i(TAG, "The purchase is still being processed; it stays recoverable.")
      state.copy(dialogs = state.dialogs.copy(purchasePending = true))
    }
    SignalLoginPurchaseStep.Redemption.ReceiptRejected -> {
      Log.w(TAG, "The purchase's proof of payment was rejected; the purchase is preserved for recovery.")
      state.copy(dialogs = state.dialogs.copy(invalidReceiptCredential = true))
    }
    is SignalLoginPurchaseStep.Redemption.NetworkError -> {
      state.copy(dialogs = state.dialogs.copy(networkError = true))
    }
    is SignalLoginPurchaseStep.Redemption.Failed -> {
      state.copy(dialogs = state.dialogs.copy(unknownError = true))
    }
    SignalLoginPurchaseStep.Redemption.NothingToRedeem -> {
      state.copy(dialogs = state.dialogs.copy(unknownError = true))
    }
  }

  /**
   * Redeems the manually-pasted receipt credential by building its presentation and registering a numberless account
   * with it, bypassing the purchase flow entirely.
   */
  private suspend fun applyManualReceiptCredentialSubmitted(
    state: SignalLoginPaymentState,
    parentEventEmitter: (RegistrationFlowEvent) -> Unit
  ): SignalLoginPaymentState {
    val presentation = try {
      repository.createReceiptCredentialPresentation(state.manualReceiptCredential.decode())
    } catch (e: Exception) {
      Log.w(TAG, "[ManualReceipt] The pasted value could not be parsed as a receipt credential.", e)
      return state.copy(dialogs = state.dialogs.copy(invalidReceiptCredential = true))
    }

    return when (val result = repository.registerAccountWithoutPhoneNumber(presentation)) {
      is RequestResult.Success -> {
        Log.i(TAG, "[ManualReceipt] Successfully registered without a phone number.")
        val (response, keyMaterial, aci) = result.result

        parentEventEmitter(RegistrationFlowEvent.Registered(aci, keyMaterial.accountEntropyPool, response.storageCapable, phoneNumberless = response.e164 == null))
        parentEventEmitter.navigateTo(RegistrationRoute.SignalLoginInfo, popCurrent = true)
        state
      }
      is RequestResult.NonSuccess -> {
        when (val error = result.error) {
          is RegisterAccountError.InvalidReceiptCredentialPresentation -> {
            Log.w(TAG, "[ManualReceipt] The service rejected the receipt credential presentation. Message: ${error.message}")
            state.copy(dialogs = state.dialogs.copy(invalidReceiptCredential = true))
          }
          is RegisterAccountError.DeviceTransferPossible -> {
            Log.w(TAG, "[ManualReceipt] Got told a device transfer is possible despite asking to skip it.")
            state.copy(dialogs = state.dialogs.copy(unknownError = true))
          }
          is RegisterAccountError.InvalidRequest -> {
            Log.w(TAG, "[ManualReceipt] Invalid request. Message: ${error.message}")
            state.copy(dialogs = state.dialogs.copy(unknownError = true))
          }
          is RegisterAccountError.RateLimited -> {
            Log.w(TAG, "[ManualReceipt] Rate limited (retryAfter: ${error.retryAfter}).")
            state.copy(dialogs = state.dialogs.copy(unknownError = true))
          }
          else -> {
            Log.w(TAG, "[ManualReceipt] Unexpected registration error for a numberless registration: $error")
            state.copy(dialogs = state.dialogs.copy(unknownError = true))
          }
        }
      }
      is RequestResult.RetryableNetworkError -> {
        Log.w(TAG, "[ManualReceipt] Network error.", result.networkError)
        state.copy(dialogs = state.dialogs.copy(networkError = true))
      }
      is RequestResult.ApplicationError -> {
        Log.w(TAG, "[ManualReceipt] Application error.", result.cause)
        state.copy(dialogs = state.dialogs.copy(unknownError = true))
      }
    }
  }

  class Factory(
    private val repository: RegistrationRepository,
    private val oneTimePurchaseApi: OneTimePurchaseApi,
    private val purchaseStore: SignalLoginPurchaseStore,
    private val parentEventEmitter: (RegistrationFlowEvent) -> Unit
  ) : ViewModelProvider.Factory {
    @Suppress("UNCHECKED_CAST")
    override fun <T : ViewModel> create(modelClass: Class<T>): T {
      return SignalLoginPaymentViewModel(
        repository = repository,
        purchaseStep = SignalLoginPurchaseStep(repository, oneTimePurchaseApi, purchaseStore),
        parentEventEmitter = parentEventEmitter
      ) as T
    }
  }

  /** Exposed so the UI layer can hand a launcher back to the API it launched with. */
  fun purchaseLauncher(): PurchaseLauncher? = (state.value.purchasePreparation as? OneTimePurchasePreparation.Ready)?.launcher
}

