  data class Issued(val credential: ReceiptCredential) : CreateLoginReceiptCredentialResult

  /** The service has not finished processing the purchase yet. The purchase remains recoverable. */
  data object Pending : CreateLoginReceiptCredentialResult

  /** The service rejected the purchase identifier outright. Retrying will not help. */
  data class InvalidPurchase(val error: CreateLoginReceiptCredentialError = CreateLoginReceiptCredentialError.InvalidPurchase) : CreateLoginReceiptCredentialResult

  /** The service is throttling us. */
  data object RateLimited : CreateLoginReceiptCredentialResult
