package org.signal.registration

import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import androidx.lifecycle.viewModelScope
import androidx.navigation3.runtime.NavBackStack
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import org.signal.core.ui.compose.EventDrivenViewModel
import org.signal.core.util.logging.Log
import org.signal.registration.screens.util.navigateBack
import org.signal.registration.screens.util.navigateTo

/**
 * Owns the registration flow itself: the back stack, and the account identity that a successful registration issues.
 *
 * The order of two events matters a great deal here. [RegistrationFlowEvent.Registered] is always processed *before*
 * the navigation that follows it, so a screen that is about to show the user their account ID and recovery key can
 * rely on [aci] and [accountEntropyPool] already being populated.
 */
class RegistrationViewModel(
  private val repository: RegistrationRepository,
  initialRoute: RegistrationRoute = RegistrationRoute.Welcome,
  private val navBackStack: NavBackStack<RegistrationRoute> = NavBackStack(initialRoute)
) : EventDrivenViewModel<RegistrationFlowEvent>(TAG), RegistrationFlowState {

  companion object {
    private val TAG = Log.tag(RegistrationViewModel::class)
  }

  /** This is where child screens publish the events they want the flow to act on. */
  private val _childEvents = MutableStateFlow<RegistrationFlowEvent?>(null)

  private val _backStack = MutableStateFlow(navBackStack.toList())
  val backStack: StateFlow<List<RegistrationRoute>> = _backStack.asStateFlow()

  override var aci: org.signal.core.models.ServiceId.ACI? = null
    private set

  override var accountEntropyPool: org.signal.core.models.AccountEntropyPool? = null
    private set

  override var isPhoneNumberlessAccount: Boolean = false
    private set

  override var registrationComplete: Boolean = false
    private set

  override var finalRegistrationCommitted: Boolean = false
    private set

  init {
    viewModelScope.launch {
      _childEvents.collect { event ->
        event?.let { onRegistrationFlowEvent(it) }
        _childEvents.value = null
      }
    }
  }

  /**
   * The emitter handed to every child screen. It funnels events through a single consumer so that ordering — in
   * particular [RegistrationFlowEvent.Registered] arriving before the navigation it precedes — is guaranteed rather
   * than merely likely.
   */
  val parentEventEmitter: (RegistrationFlowEvent) -> Unit = { event -> _childEvents.value = event }

  @VisibleForTestingOnly
  internal fun onRegistrationFlowEvent(event: RegistrationFlowEvent) {
    when (event) {
      is RegistrationFlowEvent.Registered -> {
        Log.i(TAG, "Registered. Phone numberless: ${event.phoneNumberless}")
        aci = event.aci
        accountEntropyPool = event.accountEntropyPool
        isPhoneNumberlessAccount = event.phoneNumberless
      }
      is RegistrationFlowEvent.NavigateToScreen -> {
        if (event.popCurrent) {
          navBackStack.pop()
        }
        navBackStack.add(event.route)
        publishBackStack()
      }
      is RegistrationFlowEvent.NavigateBack -> {
        navBackStack.pop()
        publishBackStack()
      }
      is RegistrationFlowEvent.NavigateBackToScreen -> {
        // Everything above the target goes away; if it isn't there at all, the target replaces the top of the stack.
        while (navBackStack.isNotEmpty() && navBackStack.last() != event.route) {
          navBackStack.pop()
        }
        if (navBackStack.isEmpty()) {
          navBackStack.add(event.route)
        }
        publishBackStack()
      }
      is RegistrationFlowEvent.ResetState -> {
        navBackStack.resetTo(RegistrationRoute.Welcome)
        aci = null
        accountEntropyPool = null
        isPhoneNumberlessAccount = false
        registrationComplete = false
        finalRegistrationCommitted = false
        publishBackStack()
      }
      is RegistrationFlowEvent.RegistrationComplete -> {
        // Asked for, but not yet committed. Only the service acknowledging the account flips
        // [finalRegistrationCommitted]; until then, nothing here may look like success.
        registrationComplete = true
      }
      else -> Log.d(TAG, "[FlowEvent] $event")
    }
  }

  /**
   * Record that the service has accepted this registration.
   *
   * A numberless account has no PIN and no phone identity, so the PIN and phone-verification steps that a normal
   * registration would insert are simply never added to the back stack.
   */
  fun onRegistrationCommitted() {
    finalRegistrationCommitted = true
  }

  /** True when the account identity the screens need is available. */
  val hasIssuedAccountIdentity: Boolean
    get() = aci != null && accountEntropyPool != null

  private fun publishBackStack() {
    _backStack.value = navBackStack.toList()
  }

  class Factory(
    private val repository: RegistrationRepository,
    private val initialRoute: RegistrationRoute = RegistrationRoute.Welcome
  ) : ViewModelProvider.Factory {
    @Suppress("UNCHECKED_CAST")
    override fun <T : ViewModel> create(modelClass: Class<T>): T = RegistrationViewModel(repository, initialRoute) as T
  }

  @androidx.annotation.VisibleForTesting
  fun navigateBack() = parentEventEmitter.navigateBack()

  @androidx.annotation.VisibleForTesting
  fun navigateTo(route: RegistrationRoute) = parentEventEmitter.navigateTo(route)
}

/** Marker for the testing affordance annotations this view model relies on. */
private annotation class VisibleForTestingOnly

