package org.signal.registration.screens.signalloginmanualsave

import androidx.annotation.VisibleForTesting
import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.launchIn
import kotlinx.coroutines.flow.onEach
import org.signal.core.ui.compose.EventDrivenViewModel
import org.signal.core.util.logging.Log
import org.signal.registration.RegistrationFlowEvent
import org.signal.registration.RegistrationFlowState
import org.signal.registration.RegistrationRoute
import org.signal.registration.screens.util.navigateBack
import org.signal.registration.screens.util.navigateTo

/**
 * Shows the issued account ID and recovery key in the form the user is meant to write down, for the case where the
 * password manager is unavailable, was cancelled, or wouldn't confirm the credential.
 *
 * Saying "I've written it down" isn't the end of it — it leads to a re-entry check that compares what was typed back
 * against what was issued. Registration can't move past that check on the strength of a button press alone.
 */
class SignalLoginViewDetailsForManualSaveViewModel(
  private val flowState: RegistrationFlowState,
  private val parentEventEmitter: (RegistrationFlowEvent) -> Unit
) : EventDrivenViewModel<SignalLoginViewDetailsForManualSaveScreenEvents>(TAG) {

  companion object {
    private val TAG = Log.tag(SignalLoginViewDetailsForManualSaveViewModel::class)
  }

  private val _state = MutableStateFlow(SignalLoginManualSaveState())
  val state: StateFlow<SignalLoginManualSaveState> = _state.asStateFlow()

  init {
    _state
      .onEach { Log.d(TAG, "[State] $it") }
      .launchIn(viewModelScope)

    val aci = checkNotNull(flowState.aci) { "Manual save requires an issued ACI" }
    val accountEntropyPool = checkNotNull(flowState.accountEntropyPool) { "Manual save requires an issued recovery key" }

    _state.value = SignalLoginManualSaveState(
      accountId = aci.toString().uppercase(),
      recoveryKey = accountEntropyPool.displayValue
    )
  }

  override suspend fun processEvent(event: SignalLoginViewDetailsForManualSaveScreenEvents) {
    applyEvent(_state.value, event, parentEventEmitter) { _state.value = it }
  }

  @VisibleForTesting
  suspend fun applyEvent(
    state: SignalLoginManualSaveState,
    event: SignalLoginViewDetailsForManualSaveScreenEvents,
    parentEventEmitter: (RegistrationFlowEvent) -> Unit,
    stateEmitter: (SignalLoginManualSaveState) -> Unit
  ) {
    when (event) {
      is SignalLoginViewDetailsForManualSaveScreenEvents.RecordedClicked -> {
        parentEventEmitter.navigateTo(RegistrationRoute.SignalLoginManualSaveConfirmation)
      }
      is SignalLoginViewDetailsForManualSaveScreenEvents.BackClicked -> {
        parentEventEmitter.navigateBack()
      }
    }
  }

  class Factory(
    private val flowState: RegistrationFlowState,
    private val parentEventEmitter: (RegistrationFlowEvent) -> Unit
  ) : ViewModelProvider.Factory {
    @Suppress("UNCHECKED_CAST")
    override fun <T : ViewModel> create(modelClass: Class<T>): T {
      return SignalLoginViewDetailsForManualSaveViewModel(flowState, parentEventEmitter) as T
    }
  }
}

