package org.signal.registration.screens.addusername

sealed class AddUsernameScreenEvents {
  /** The user edited the nickname field. */
  data class NicknameChanged(val value: String) : AddUsernameScreenEvents()

  /** The user edited the discriminator field. */
  data class DiscriminatorChanged(val value: String) : AddUsernameScreenEvents()

  /** The discriminator field gained or lost focus. */
  data class DiscriminatorFocusChanged(val focused: Boolean) : AddUsernameScreenEvents()

  /** The discriminator field lost focus. This is the only moment a service-assigned discriminator may be fetched. */
  data object DiscriminatorFocusLost : AddUsernameScreenEvents()

  /** The user is happy with the reserved username and wants to take it. */
  data object NextClicked : AddUsernameScreenEvents()

  /** The user asked to skip claiming a username. A request only — see [SkipConfirmed]. */
  data object SkipClicked : AddUsernameScreenEvents()

  /** The user confirmed, in the skip dialog, that they really want to finish without a username. */
  data object SkipConfirmed : AddUsernameScreenEvents()

  /** The user dismissed the skip dialog. */
  data object SkipDialogDismissed : AddUsernameScreenEvents()

